// Get all email items from merge (could include phantom empties from alwaysOutputData)
const emailItems = $('Merge Email Results').all();

// Get trip log binary and parse existing email IDs
let existingEmailIds = new Set();
try {
  const tripLogBinary = $('Download Trip Log').first().binary?.triplog;
  if (tripLogBinary) {
    const tripLogText = Buffer.from(tripLogBinary.data, 'base64').toString('utf8');
    const tripLog = JSON.parse(tripLogText);
    if (tripLog.entries) {
      for (const entry of tripLog.entries) {
        if (entry.email_id) existingEmailIds.add(entry.email_id);
      }
    }
  }
} catch (e) {
  // Trip log empty or parse error — no existing IDs
}

// Filter: only real emails (have an id) that haven't been processed yet
const newEmails = emailItems.filter(item => {
  const json = item.json;
  return json.id && json.id.length > 0 && !existingEmailIds.has(json.id);
});

if (newEmails.length === 0) {
  return [{ json: { hasNew: false, count: 0, emails: [] } }];
}

// Build condensed email summaries for Claude classification
const emailSummaries = newEmails.map(item => {
  const json = item.json;
  // Extract plain text body, truncate to save tokens
  const body = (json.textPlain || json.snippet || '').substring(0, 1500);
  return {
    email_id: json.id,
    subject: json.subject || '',
    from: json.from?.text || json.from || '',
    date: json.date || json.internalDate || '',
    body: body,
    labels: json.labelIds || []
  };
});

return [{
  json: {
    hasNew: true,
    count: emailSummaries.length,
    emails: emailSummaries,
    existingEntryCount: existingEmailIds.size
  }
}];

// Parse Claude's classification output
const llmOutput = $input.first().json.text || $input.first().json.output || '';
let classifications;
try {
  // Extract JSON array from response (handle markdown code blocks)
  const jsonMatch = llmOutput.match(/\[\s*\{[\s\S]*\}\s*\]/)
  classifications = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(llmOutput);
} catch (e) {
  return [{ json: { error: 'Failed to parse LLM output', raw: llmOutput, newEntries: 0 } }];
}

// Filter to confirmed bookings only
const bookings = classifications.filter(c => c.is_booking === true);

if (bookings.length === 0) {
  return [{ json: { newEntries: 0, message: 'No confirmed bookings found in new emails' } }];
}

// Download and parse existing trip log
let tripLog;
try {
  const tripLogBinary = $('Download Trip Log').first().binary?.triplog;
  const tripLogText = Buffer.from(tripLogBinary.data, 'base64').toString('utf8');
  tripLog = JSON.parse(tripLogText);
} catch (e) {
  tripLog = { version: '1.0', entries: [] };
}

// Build new entries
const now = new Date().toISOString();
for (const booking of bookings) {
  tripLog.entries.push({
    id: `email_${booking.email_id.substring(0, 12)}`,
    timestamp: now,
    type: `email_${booking.type}`,
    trip: booking.trip_guess || 'unknown',
    source_email: 'auto_detected',
    email_id: booking.email_id,
    confirmation_number: booking.confirmation_number || null,
    provider: booking.provider || '',
    destination: booking.destination || '',
    dates: booking.dates || null,
    details: booking.details || '',
    note: `Auto-extracted from email on ${now.split('T')[0]}`,
    tags: ['email_scan', booking.type]
  });
}

// Convert to binary for Drive upload
const updatedJson = JSON.stringify(tripLog, null, 2);
const base64 = Buffer.from(updatedJson, 'utf8').toString('base64');

return [{
  json: {
    newEntries: bookings.length,
    totalEntries: tripLog.entries.length,
    bookingSummary: bookings.map(b => `${b.type}: ${b.provider} — ${b.destination} (${b.dates?.start || 'TBD'})`)
  },
  binary: {
    triplog: {
      data: base64,
      mimeType: 'application/json',
      fileName: 'trip_log.json'
    }
  }
}];
